   "titolo": "La Germania punta a ospitare i Mondiali di hockey escludendo la squadra russa",
   "orig": "Germany hopes to host world ice hockey championship — without Russia",
   "lead": "La Germania intende organizzare la prossima edizione dei campionati mondiali di hockey su ghiaccio escludendo la partecipazione della nazionale russa. La decisione della federazione tedesca giunge a seguito di una sentenza giudiziaria internazionale che ha stabilito la riammissible degli atleti russi nelle competizioni ufficiali della disciplina. Le autorità sportive di Berlino stanno cercando soluzioni organizzative e diplomatiche per consentire lo svolgimento regolare del torneo nel rispetto delle proteste internazionali sollevate contro la decisione del tribunale. Lo riferisce Deutsche Welle.",
