   "orig": "Amid protests, France's rising debt costs threaten stability",
   "lead": "Il governo francese ha annunciato l'intenzione di stanziare 4 miliardi di euro aggiuntivi a favore del sistema scolastico pubblico, in un momento segnato da forti proteste sociali a livello nazionale. Tuttavia, il continuo aumento del debito pubblico e la crescita dei tassi di interesse sui titoli di Stato riducono notevolmente il margine di manovra finanziario delle istituzioni di Parigi, sollevando preoccupazioni sulla tenuta dei conti pubblici e sulla stabilità complessiva del piano economico di bilancio. Lo riferisce Deutsche Welle.",
