   "lead": "La Corte Suprema dell'India è intervenuta sul problema dell'inquinamento atmosferico nella capitale Nuova Delhi, individuando nel traffico veicolare una delle cause primarie del deterioramento della qualità dell'aria. I giudici hanno rivolto un appello formale alla popolazione affinché mantenga comportamenti responsabili durante le imminenti festività tradizionali, in particolare nel corso dei festeggiamenti per la ricorrenza di Diwali, evitando l'uso eccessivo di fuochi d'artificio capaci di aggravare ulteriormente la concentrazione di polveri sottili. Lo riferisce Deutsche Welle.",
