   "lead": "Gli allenatori di diverse selezioni calcistiche africane hanno ufficializzato le liste dei convocati per le imminenti partite di qualificazione alla Coppa d'Africa 2027 e ai tornei di categoria U-23. Il commissario tecnico della Tunisia Mouine Chaabani ha reso noti i giocatori scelti per la doppia sfida contro la Libia, mentre Brahim Hemdani ha convocato 26 elementi per l'Algeria in vista del doppio impegno con il Togo. Contestualmente, le selezioni giovanili di Guinea e Madagascar preparano i propri confronti decisivi rispettivamente contro Botswana e Sudafrica.",
