   "orig": "Kellogg's admits snap, crackle and pop is quieter after uproar over Rice Krispies recipe change",
   "lead": "La multinazionale agroalimentare Kellogg's ha ammesso che il celebre scoppiettio dei propri cereali Rice Krispies e Coco Pops è diventato meno udibile a causa di una recente modifica apportata alla ricetta sul mercato europeo. La variazione nella formulazione degli ingredienti ha eliminato l'impiego di determinati chicchi di riso integrali, provocando una reazione di disappunto da parte dei consumatori sui social network per il cambiamento del sapore e dell'inconfondibile rumore croccante delle prime colazioni.",
