   "titolo": "Guida agli avvistamenti per la pioggia di meteore delle Leonid e delle Tauridi",
   "orig": "Everything you need to know about the Leonid Meteor Shower",
   "lead": "Gli appassionati di astronomia si preparano a osservare lo sciame meteorico delle Leonid, il cui picco di visibilità è previsto per le serate del 17 e 18 novembre. Nella medesima fase di osservazione autonoma, la presenza della luna nuova all'inizio del mese offre le condizioni ideali per scorgere le meteore e le scie luminose del fenomeno delle Tauridi Nord, rendendo il cielo notturno particolarmente propizio per l'avvistamento delle stelle cadenti in diverse regioni del pianeta.",
