   "id": "z80d77516",
   "sez": "dibattito",
   "titolo": "Polemica in Francia sull'uso della divisa dell'École polytechnique nelle manifestazioni",
   "orig": "L’École polytechnique «condamne formellement» le port du grand uniforme en manifestation",
   "lead": "L'École polytechnique di Parigi ha criticato la scelta di alcuni ex studenti che hanno sfilato in uniforme ufficiale durante la manifestazione politica del 5 novembre a Parigi. L'istituto universitario ha dichiarato in una nota che l'abito tradizionale non deve essere strumentalizzato per scopi politici. Gli ex allievi sostengono la propria libertà di espressione portando i simboli dell'ateneo, mentre la direzione ribadisce la necessità di mantenere l'indipendenza dell'istituto da qualsiasi schieramento, aprendo un dibattito sul rispetto della neutralità delle storiche istituzioni pubbliche.",
   "more": [
    "L'École polytechnique è una delle istituzioni di alta formazione ingegneristica e scientifica più prestigiose della Francia, storicamente legata all'amministrazione dello Stato e al ministero della Difesa. L'uso del \"grand uniforme\" nelle manifestazioni solleva questioni sul confine tra la libertà d'espressione del singolo e la tutela della neutralità delle istituzioni statali di cui la divisa è rappresentazione pubblica."
   ],
