   "orig": "A Palermo un tempo si mangiavano pesci fatti con la farina di ceci. La storia delle panelle",
   "lead": "La preparazione delle tradizionali panelle di Palermo, realizzate miscelando farina di ceci, acqua e olio di frittura, costituisce un elemento centrale dello street food siciliano. In passato queste frittelle venivano modellate a forma di piccolo pesce e consumate in prevalenza durante le celebrazioni della festa di Santa Lucia, per sostituire le pietanze a base di carne e cereali in osservanza delle usanze devozionali storiche della città. Lo riferisce Gambero Rosso.",
