   "lead": "Il governo del Vietnam ha sottoposto all'Assemblea Nazionale un pacchetto di misure di incentivo volte a promuovere mega-progetti turistici dal valore superiore ai 30.000 miliardi di dong. La proposta prevede l'esenzione totale dall'imposta sui redditi delle società fino a quattro anni e la concessione di licenze operative fino a 70 anni per favorire lo sviluppo di aree di intrattenimento attive 24 ore su 24 e rilanciare l'attrattività del Paese verso gli investitori stranieri.",
