   "sez": "manga",
   "titolo": "Selezionati tre progetti pilota di anime per la prima call di Project PRISMation",
   "orig": "Abema Selects Project PRISMation's 1st Open Call Finalists to Make 3 Pilot Anime",
   "lead": "La piattaforma streaming giapponese Abema ha annunciato i vincitori finalisti della prima chiamata aperta del concorso Project PRISMation, selezionando tre opere destinate a diventare pilot animati. I progetti scelti per la produzione si intitolano OXY-HEAVEN, Amneka e Kandy-Killers for Hire. La realizzazione e la pubblicazione dei tre episodi pilota sono programmate a partire dal 2027 o negli anni successivi. Lo riferisce Anime News Network.",
   "more": [
    "Gli episodi pilota nel settore dell'animazione consentono agli studi di produzione e alle piattaforme di streaming di valutare il gradimento del pubblico e il potenziale commerciale di una nuova storia prima di investire nella creazione di una serie completa."
   ],
