   "id": "za42c5295",
   "sez": "ambiente",
   "titolo": "La ministra dell'Ambiente della Namibia sollecita trasparenza ai nuovi consigli di amministrazione",
   "orig": "Hit the ground running– tourism minister to new NWR, gambling board",
   "lead": "A Windhoek, la ministra dell'Ambiente, delle Foreste e del Turismo della Namibia, Indileni Daniel, ha rivolto un appello ai nuovi membri dei consigli di amministrazione di Namibia Wildlife Resorts e del Gambling Board of Namibia. Durante l'incontro istituzionale di venerdì, la ministra ha chiesto la massima trasparenza, responsabilità e innovazione, invitando i consiglieri ad agire con tempestività e a dare priorità allo sviluppo sostenibile del Paese. Lo riferisce The Namibian.",
   "more": [
    "Le aziende pubbliche per la gestione delle riserve e del turismo in Namibia svolgono un ruolo di primaria importanza per la conservazione della biodiversità. Il settore turistico rappresenta una voce fondamentale dell'economia del Paese africano, sostenendo l'occupazione e la salvaguardia dell'ambiente."
   ],
