   "sez": "sport",
   "titolo": "Lotta per la presidenza della FIFA e sostegno dei paesi caraibici a Gianni Infantino",
   "orig": "Infantino caught in the web as tide turns against Trump in midterms and leaves Fifa exposed | Barney Ronay",
   "lead": "La competizione per la presidenza della FIFA in vista delle elezioni del prossimo marzo ha innescato forti tensioni nell'organizzazione del calcio mondiale. Nella lotta di potere aperta dopo la Coppa del Mondo del 2026, l'associazione calcistica dei Caraibi ha espresso ufficialmente il proprio sostegno al presidente uscente Gianni Infantino. Il contesto politico e i recenti cambiamenti istituzionali internazionali pongono tuttavia la governance della federazione sotto una crescente pressione mediatica e diplomatica.",
   "more": [
    "La FIFA gestisce il calcio a livello mondiale ed elegge il proprio presidente attraverso il voto delle federazioni nazionali affiliate. Il peso dei blocchi regionali, come le confederazioni del Nord e Centro America e dei Caraibi, risulta determinante nelle scadenze elettorali."
   ],
