   "sez": "salute",
   "titolo": "Negli Stati Uniti registrato il picco di casi di morbillo degli ultimi 35 anni",
   "orig": "US reports highest number of measles cases in 35 years",
   "lead": "Negli Stati Uniti i casi accertati di morbillo hanno superato quota 5.000 dall'inizio dell'anno, segnando il livello più alto registrato nel Paese negli ultimi 35 anni. Il bilancio epidemiologico ufficiale diffuso dalle autorità sanitarie venerdì attesta un sensibile incremento dei contagi virali su scala nazionale, riaccendendo l'allarme dei medici e degli esperti di salute pubblica in merito alla flessione della copertura vaccinale. Lo riferisce Medical Xpress.",
   "more": [
    "Il morbillo è una malattia infettiva highly contagiosa provocata da un virus che può causare gravi complicazioni. La diminuzione dei tassi di vaccinazione pediatrica negli ultimi anni ha portato alla ricomparsa di focolai in diverse regioni sviluppate."
   ],
