   "titolo": "La Banca Nazionale della Moldavia sospende la licenza dell'istituto BPAY per sei mesi",
   "orig": "The National Bank of Moldova has suspended BPAY’s licence for six months",
   "lead": "La Banca Nazionale della Moldavia ha disposto la sospensione temporanea per una durata di sei mesi della licenza operativa di BPAY, istituto di pagamento non bancario ed emittente di moneta elettronica nel Paese. La decisione formale dell'autorità bancaria centrale è arrivata al termine di una serie di ispezioni che hanno evidenziato significative irregolarità nella gestione dei servizi finanziari erogati dalla società. Lo riferisce IPN (inglese).",
   "more": [
    "Le autorità di vigilanza bancaria monitorano costantemente i fornitori di servizi di pagamento elettronico per verificare la conformità alle norme antiriciclaggio e di trasparenza. La sospensione delle licenze protegge il sistema finanziario e i risparmi dei clienti da irregolarità operative."
   ],
