   "titolo": "Zenith Bank assegna 190 milioni di naira agli innovatori africani al sesto tech fair",
   "orig": "Zenith Bank awards N190m to African innovators at sixth tech fair",
   "lead": "In Nigeria la Zenith Bank ha premiato con un ammontare totale di 190 milioni di naira gli innovatori africani vincitori della sesta edizione della sua fiera tecnologica. Attraverso il lancio della competizione Future Innovators Challenge, l'istituto di credito ha esteso il sostegno economico agli studenti delle scuole secondarie, puntando a identificare e sviluppare precocemente i giovani talenti nel settore dell'innovazione digitale. Lo riferisce Premium Times.",
   "more": [
    "Gli investimenti del settore bancario africano nel campo dell'innovazione tecnologica puntano a sostenere l'imprenditoria giovanile e lo sviluppo delle startup locali. Il finanziamento di progetti scolastici e universitari favorisce l'inclusione digitale e la crescita dell'ecosistema tecnologico regionale."
   ],
