   "id": "zb1536b98",
   "sez": "mondo",
   "titolo": "Sud Sudan: appello ai giornalisti per denunciare l'uso dei bambini nei conflitti armati",
   "orig": "Journalists urged to expose use of children in armed conflict",
   "lead": "L'organizzazione no-profit canadese per lo sviluppo dei media Journalists for Human Rights ha rivolto un urgente appello ai giornalisti del Sud Sudan affinché denuncino con forza il reclutamento e l'impiego dei minori nei conflitti armati. La sollecitazione mira a sensibilizzare l'opinione pubblica e le autorità sulla grave violazione dei diritti umani che colpisce i bambini coinvolti nelle ostilità nel Paese africano, incoraggiando gli operatori dell'informazione a svolgere un ruolo attivo nell'evidenziare queste drammatiche realtà sul campo. Lo riferisce Radio Tamazuj.",
   "more": [
    "Il reclutamento di bambini soldato rappresenta una drammatica violazione del diritto internazionale umanitario e dei diritti dell'infanzia. In molti contesti di guerra civile o instabilità politica, i gruppi armati sfruttano i minori per compiti di combattimento, supporto logistico o spionaggio, privandoli dell'istruzione, della tutela familiare e di un futuro pacifico."
   ],
