   "id": "z21b430b5",
   "sez": "italia",
   "titolo": "Italia: nei territori torna a crescere la sindrome Nimby contro opere pubbliche e infrastrutture",
   "orig": "Opere pubbliche e infrastrutture a km 0, sui territori si riacutizza la sindrome di Nimby, “non nel mio cortile”",
   "lead": "In Italia si registra una riacutizzazione della sindrome oppositiva conosciuta come Nimby, acronimo dell'espressione inglese Not In My Back Yard. Questa tendenza sociale vede comitati locali e comunità territoriali schierarsi con decisione contro la realizzazione di opere pubbliche e nuove infrastrutture nei propri comuni o quartieri. Il fenomeno evidenzia la crescente difficoltà nel mediare tra l'interesse strategico nazionale per lo sviluppo delle opere pubbliche e le resistenze delle popolazioni locali preoccupate dall'impatto sul proprio territorio. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "La sindrome Nimby descrive l'atteggiamento dei cittadini che riconoscono la necessità di determinati impianti o infrastrutture strategiche, ma si oppongono fermamente alla loro installazione vicino al proprio luogo di residenza. La gestione di tali conflitti richiede solitamente processi avanzati di partecipazione pubblica e consultazione preventiva dei territori interessati."
   ],
