   "id": "za9f72db9",
   "sez": "viaggi",
   "titolo": "Turismo di lusso in Italia: spesa di 10,4 miliardi negli hotel a cinque stelle nel 2025",
   "orig": "Il turismo negli alberghi di lusso vale 10,4 miliardi, dal 2008 presenze più che raddoppiate",
   "lead": "Il settore del turismo di lusso negli alberghi italiani sta attraversando una fase di straordinaria espansione economica. Nel 2025 la spesa complessiva generata dai clienti delle strutture ricettive a 5 stelle e 5 stelle lusso ha raggiunto la quota di 10,4 miliardi di euro. I dati confermano una traiettoria di crescita costante per l'ospitalità di alta gamma nel Paese, evidenziando come le presenze dei turisti in questa categoria di hotel siano più che raddoppiate rispetto ai livelli registrati nel 2008. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Il turismo d'alta gamma rappresenta un segmento ad alto valore aggiunto per l'economia italiana, in grado di attrarre visitatori internazionali con un'elevata capacità di spesa. Questo comparto stimola non solo l'accoglienza alberghiera, ma anche la ristorazione stellata, l'artigianato di pregio, il commercio di beni di lusso e i servizi di trasporto privati."
   ],
