   "id": "z96f465bc",
   "sez": "italia",
   "titolo": "Scontro politico sul web: foto ritoccata di Tajani con il cappello Maga, Bonaccini rimuove il post",
   "orig": "Tajani con cappellino Maga, Forza Italia contro Bonaccini: «Foto falsa». Il presidente del Pd rimuove il post",
   "lead": "Una polemica politica si è accesa dopo la pubblicazione da parte del presidente del Partito Democratico, Stefano Bonaccini, di un messaggio social contenente una foto modificata del ministro degli Esteri Antonio Tajani con indosso il cappellino con lo slogan trumpiano Make America Great Again. Forza Italia ha subito protestato denunciando la falsità dell'immagine pubblicata insieme alla didascalia Mai stati trumpiani. Di fronte alle contestazioni sollevate dagli alleati di governo e dal partito di Tajani, Bonaccini ha provveduto a rimuovere il post. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Le dinamiche della comunicazione politica sui social network vedono spesso un uso rapido di immagini e contenuti multimediali che possono generare accese controversie sulla loro veridicità. La diffusione di immagini alterate o decontestualizzate da parte di figure pubbliche pone regolarmente il tema della verifica delle fonti e della responsabilità nelle interazioni digitali."
   ],
