   "id": "za1f8e58b",
   "sez": "economia",
   "titolo": "Sicilia: 15 milioni di euro non spesi per i ristori sul gasolio agli autotransportatori",
   "orig": "Caro gasolio e tir, in Sicilia 15 milioni fermi: ma le domande scadono a fine mese",
   "lead": "In Sicilia restano fermi 15 milioni di euro destinati al ristoro delle imprese di autotrasporto per l'aumento dei costi del carburante sostenuti tra marzo e dicembre. Nonostante le domande per accedere ai contributi debbano essere inviate tassativamente entro la scadenza del 30 novembre, a meno di un mese dal termine molte aziende del settore non hanno ancora completato le procedure di richiesta. La situazione solleva forte preoccupazione per il rischio di perdere fondi decisivi per sostenere il settore dei trasporti. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Il settore dell'autotrasporto risente pesantemente delle fluttuazioni dei prezzi dei carburanti, che incidono sui costi operativi delle aziende merci. Le sovvenzioni pubbliche e i ristori sul gasolio rappresentano misure temporanee di sostegno pensate per mitigare l'impatto dell'inflazione energetica e garantire la continuità della catena di distribuzione logistica sui territori regionali."
   ],
