   "id": "zdd0ac08d",
   "sez": "economia",
   "titolo": "Manovra economica: al via la settimana di audizioni parlamentari a Montecitorio",
   "orig": "Manovra, settimana di fuoco tra audizioni e incontri: il calendario e chi verrà ascoltato dal Governo",
   "lead": "Il percorso parlamentare della nuova legge di Bilancio entra nel vivo a Montecitorio con un'intensa giornata di lavori coordinati dalle commissioni Bilancio di Camera e Senato. Lunedì 9 novembre si terrà una maratona di audizioni di quasi nove ore nella Sala del Mappamondo, programmata dalle 11:00 alle 19:50, durante la quale il Governo e i parlamentari ascolteranno i rappresentanti delle principali istituzioni, parti sociali e categorie economiche prima dell'esame del testo finanziario. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "L'esame della legge di Bilancio in Parlamento prevede una prima fase riservata alle audizioni conoscitive degli enti pubblici, delle organizzazioni sindacali e delle associazioni di categoria. Questo passaggio consente alle commissioni competenti di valutare l'impatto economico delle misure proposte nella manovra prima dell'avvio della discussione degli emendamenti e del voto finale."
   ],
