   "id": "z89408a5d",
   "sez": "prima",
   "titolo": "India: atterraggio da record per un aereo militare IL-76 nella base di Nyoma in Ladakh",
   "orig": "Watch: IAF IL-76 makes world-record landing in Ladakh's Nyoma",
   "lead": "Un velivolo da trasporto pesante IL-76MD dell'Aeronautica militare indiana è atterrato con successo presso la base aerea di Mudh-Nyoma nel territorio del Ladakh, stabilendo un record storico per questa classe di aerei. Situata a un'altitudine di oltre 4.100 metri nei pressi della Linea di Controllo Effettivo alla frontiera con la Cina, l'infrastruttura di Nyoma rappresenta uno degli aeroporti militari più alti al mondo in grado di gestire caccia e aerei da trasporto per lo spostamento rapido di truppe ed equipaggiamenti.",
   "more": [
    "Il territorio dell'alto Ladakh lungo il confine tra India e Cina costituisce una zona di rilevanza strategica soggetta a periodiche tensioni bilaterali. L'ammodernamento delle basi ad alta quota consente di garantire un supporto logistico continuo alle forze di difesa posizionate in aree montuose impervie e isolate durante tutto l'anno."
   ],
