   "id": "zb4a5fe81",
   "sez": "mondo",
   "titolo": "Unione Europea: la Repubblica Ceca potrà beneficiare di esenzioni dal meccanismo di solidarietà migratoria",
   "orig": "EC: Czechia eligible for exemption from EU migration solidarity mechanism",
   "lead": "La Commissione Europea ha stabilito che la Repubblica Ceca possiede i requisiti necessari per beneficiare di un'esenzione dai contributi obbligatori previsti dal meccanismo europeo di solidarietà sui migranti. La decisione tiene conto dell'elevato sforzo sostenuto da Praga nell'accoglienza di decine di migliaia di profughi ucraini. Allo stesso tempo, le ultime valutazioni dell'esecutivo comunitario hanno inserito la Croazia tra i Paesi membri identificati a rischio di sostenere forti pressioni migratorie lungo le rotte regionali.",
   "more": [
    "Il nuovo Patto europeo sulla migrazione e l'asilo prevede un meccanismo di solidarietà obbligatoria ma flessibile tra i Paesi dell'Unione Europea. Gli Stati membri possono contribuire ricollocando richiedenti asilo oppure fornendo aiuti finanziari o operativi, con la possibilità di richiedere deroghe temporanee se già sottoposti a forte pressione migratoria."
   ],
