   "titolo": "Singapore: i passeggeri diffidenti verso la sperimentazione sulle scale mobili della metropolitana",
   "orig": "Stand on either side of escalators? Commuters reluctant to ditch 'keep left' habit in SMRT trial",
   "lead": "Nella stazione metropolitana di City Hall a Singapore, la sperimentazione avviata dalla società dei trasporti SMRT per invitare i passeggeri a stare fermi su entrambi i lati delle scale mobili si scontra con la riluttanza dei pendolari. Gli utenti continuano a mantenere l'abitudine di occupare solo il lato sinistro lasciando libera la destra per chi cammina. Dalle rilevazioni effettuate, chi sale i gradini a destra impiega circa 20 secondi contro i 30 secondi necessari rimanendo fermi a sinistra.",
   "more": [
    "Il galateo delle scale mobili nei trasporti pubblici urbani vede da decenni l'indicazione di occupare un solo lato per consentire il sorpasso. Tuttavia, studi di mobilità dimostrano che occupare entrambi i lati fermandosi aumenta la capacità complessiva dell'impianto e riduce i tempi d'attesa nelle stazioni affollate."
   ],
