   "sez": "mondo",
   "titolo": "Kenya: la famiglia dell'avvocato rapito Abshir Abdi individua due agenti coinvolti",
   "orig": "Family identifies two security officers involved in Abshir Abdi abduction",
   "lead": "La famiglia di Abshir Ahmedsadak Abdi, avvocato di Nairobi vittima di un rapimento, ha dichiarato di aver identificato due agenti dei servizi di sicurezza presuntamente coinvolti nell'abduzione del loro congiunto. I familiari sollecitano una pronta risposta dalle istituzioni del Kenya affinché vengano avviate indagini trasparenti per far luce sulle responsabilità degli elementi delle forze dell'ordine accusati di aver preso parte al sequestro del legale sul territorio della capitale.",
   "more": [
    "I casi di rapimento o sparizione forzata che coinvolgono figure dell'avvocatura e attivisti dei diritti umani sollevano gravi preoccupazioni sulla tutela dello Stato di diritto in vari Paesi. Le associazioni forensi chiedono costantemente garanzie di sicurezza per l'esercizio della professione legale e il rispetto delle procedure giudiarie."
   ],
