     "n": "LSM",
     "c": "Riga",
     "p": "XX",
     "t": "L'articolo non è leggibile e il giudizio risulta parziale. Come voce della Lettonia, LSM riporta in modo neutro l'offerta dell'Agenzia statale per l'impiego per apprendere o migliorare gratuitamente le competenze nella «lingua lettone», al fine di favorire la competitività dei lavoratori.",
     "b": "t"
