     "t": "Come voce del Bhutan, il canale presenta in tono informativo la spedizione di quattro tennisti nazionali alla Coppa Davis in Vietnam. Vengono dettagliati i tre mesi di preparazione fisica guidata dal coach Tashi Dorji e riportate le dichiarazioni di fiducia dei giovani atleti partecipanti.",
