     "p": "XX",
     "t": "Offre una panoramica dettagliata sul vertice ad Astana e sull'uso dell'«intelligenza artificiale» da parte di gruppi terroristici. Riporta la proposta di Mirziyoyev di un ufficio ONU, evidenziando le minacce digitali regionali, la nuova legge sull'estremismo e il presunto attacco informatico ai dati di «27 milioni» di cittadini. Il resoconto è informativo.",
